const reelId = Number($json.id ?? $json.reel_id);
if (!Number.isSafeInteger(reelId) || reelId <= 0) {
  throw new Error('A positive Reel id is required.');
}

return {
  reel_id: reelId,
  pipeline_version: '__PIPELINE_VERSION_SPRINT_3__',
  contract_version: '__CONTRACT_VERSION__',
  language_hint: $json.language_hint ?? null,
  retry_of_attempt_id: $json.retry_of_attempt_id ?? null,
};

const uuidV4 = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
  const random = Math.floor(Math.random() * 16);
  const value = character === 'x' ? random : (random & 0x3) | 0x8;
  return value.toString(16);
});

return { ...$json, attempt_id: uuidV4() };

const attempt = $('DB — Criar tentativa processing').item.json;
const parse = (value) => {
  let parsed = value;
  for (let depth = 0; depth < 3 && typeof parsed === 'string'; depth += 1) {
    try {
      parsed = JSON.parse(parsed);
      continue;
    } catch {}

    const separator = parsed.indexOf(' - ');
    if (separator === -1) break;
    parsed = parsed.slice(separator + 3);
  }
  return parsed;
};
const candidates = [
  $json,
  $json.body,
  $json.error?.body,
  $json.error?.message,
  $json.error?.response?.body,
  $json.error?.response?.data,
].map(parse);
const envelope = candidates.find((value) => value && typeof value === 'object'
  && typeof value.error_code === 'string'
  && typeof value.stage === 'string'
  && typeof value.message === 'string'
  && typeof value.retryable === 'boolean');

if (envelope && (envelope.attempt_id === null || envelope.attempt_id === attempt.attempt_id)) {
  return {
    attempt_id: attempt.attempt_id,
    error_code: envelope.error_code,
    error_stage: envelope.stage,
    error_message: envelope.message,
    retryable: envelope.retryable,
  };
}

return {
  attempt_id: attempt.attempt_id,
  error_code: 'RESULT_UNKNOWN',
  error_stage: 'orchestration',
  error_message: 'Enricher request failed without a valid correlated error envelope',
  retryable: true,
};
